#include <vector>
#include <random>
#include <cmath>

class vec3 {
public:
    double x, y, z;
    vec3() : x(0), y(0), z(0) {}
    vec3(double x, double y, double z) : x(x), y(y), z(z) {}
    vec3 operator+(const vec3& v) const { return vec3(x + v.x, y + v.y, z + v.z); }
    vec3 operator-(const vec3& v) const { return vec3(x - v.x, y - v.y, z - v.z); }
    vec3 operator*(double s) const { return vec3(x * s, y * s, z * s); }
    vec3 operator/(double s) const { return vec3(x / s, y / s, z / s); }
};

void initializeVelocitiesMB(std::vector<vec3>& velocities, const std::vector<double>& masses, double temperature) {
    // Initialize random number generator
    static std::mt19937 gen(std::random_device{}());

    // Total mass and momentum
    double total_mass = 0.0;
    vec3 total_momentum;

    // Initialize velocities from Maxwell-Boltzmann distribution
    for (size_t i = 0; i < velocities.size(); ++i) {
        double stddev = std::sqrt(temperature / masses[i]);
        std::normal_distribution<double> dist(0.0, stddev);

        velocities[i].x = dist(gen);
        velocities[i].y = dist(gen);
        velocities[i].z = dist(gen);

        // Accumulate total mass and momentum
        total_mass += masses[i];
        total_momentum = total_momentum + velocities[i] * masses[i];
    }

    // Remove center of mass motion
    vec3 com_velocity = total_momentum / total_mass;
    for (auto& v : velocities) {
        v = v - com_velocity;
    }
}

