// Box-Muller transform for Gaussian random numbers
double gaussian_random(double mean, double stddev) {
    static double spare;
    static bool has_spare = false;

    if (has_spare) {
        has_spare = false;
        return mean + stddev * spare;
    }

    has_spare = true;
    double u, v, s;
    do {
        u = (rand() / ((double)RAND_MAX)) * 2.0 - 1.0;
        v = (rand() / ((double)RAND_MAX)) * 2.0 - 1.0;
        s = u * u + v * v;
    } while (s >= 1.0 || s == 0.0);

    s = std::sqrt(-2.0 * std::log(s) / s);
    spare = v * s;
    return mean + stddev * u * s;
}

void initializeVelocitiesMB(std::vector<vec3>& velocities, const std::vector<double>& masses, double temperature) {
    // Seed the random number generator
    std::srand(std::time(0));

    // Total mass and momentum
    double total_mass = 0.0;
    vec3 total_momentum;

    // Initialize velocities from Maxwell-Boltzmann distribution
    for (size_t i = 0; i < velocities.size(); ++i) {
        double stddev = std::sqrt(temperature / masses[i]);

        velocities[i].x = gaussian_random(0.0, stddev);
        velocities[i].y = gaussian_random(0.0, stddev);
        velocities[i].z = gaussian_random(0.0, stddev);

        // Accumulate total mass and momentum
        total_mass += masses[i];
        total_momentum = total_momentum + velocities[i] * masses[i];
    }

    // Remove center of mass motion
    vec3 com_velocity = total_momentum / total_mass;
    for (auto& v : velocities) {
        v = v - com_velocity;
    }
}

